"key field":"Variant ID",
"fields group data key":["phenotype","ancestry","sex"],
"fields to compare":["Ancestry","-log10(P-Value)","P-Value","Beta","MAF","Standard Error","Z Score"]
}

filters:
[
{
                "field": "Variant ID",
                "label": "Variant ID",
                "type": "search",
"label in bubble":"true"
            },
{
                "field": "P-Value",
                "label": "P-Value (<=)",
                "type": "search lower than",
"label in bubble":"true"
            },
{
                "field": "MAF",
                "label": "MAF (>=)",
                "type": "search greater than",
"label in bubble":"true"
            },
{
                "field": "Beta",
                "label": "Beta (>=)",
                "type": "search greater than",
"label in bubble":"true"
            },
{
                "field": "Z Score",
                "label": "Z Score (>=)",
                "type": "search greater than",
