visualizerConfiguration:
{"type":"gem package",
"viewers": ["region plot", "genes plot","annotations plot","gene-links plot"],
"pkg id": "testPkg",
"region viewer": {
  "x axis field": "Position",
  "y axis field": "-log10(P-Value)",
  "render by": "Variant ID",
  "y axis label": "-Log10(p-value)",
  "x axis label": "Chromosome",
  "hover content": ["P-Value", "Beta"],
  "height": 120,
"star key":"Variant ID",
  "ld server": {"pos": "Position","ref": "ref","alt": "alt","ref variant field": "Variant ID","populations field": "Ancestry","populations type": "dynamic","populations": { "Mixed":"ALL","EU":"EUR","AA":"AFR","EA":"EAS","HS":"AMR","SA":"SAS" }}
  },
"credible sets viewer":{
  "credible sets server":"KP BioIndex",
  "phenotype parameter":"phenotype",
  "x axis field": "position",
  "y axis field": "posteriorProbability",
  "hover content":["posteriorProbability","credibleSetId"],
  "render by":"Variant ID",
  "data convert":[
    {"type":"join multi","field name":"Variant ID","fields to join":["chromosome","position","reference","alt"],"join by":[":","_","/"]}
  ],
  "phenotype match":{
"BMI_GIANT":"BMI","HEIGHT_GIANT":"HEIGHT","WHRadjBMI_GIANT":"WHRadjBMI","WHRU_GIANT":"WHR"
}
},
"annotations viewer":{
  "annotations server":"KP BioIndex",
  "phenotype parameter":"phenotype",
  "phenotype match":{
"BMI_GIANT":"BMI","HEIGHT_GIANT":"HEIGHT","WHRadjBMI_GIANT":"WHRadjBMI","WHRU_GIANT":"WHR"
},
"star key":{"key":"Variant ID","position":"Position"}
},
"gene-links viewer":{
  "with annotations viewer":"true",
  "gene links server":"KP BioIndex",
  "phenotype parameter":"phenotype",
"phenotype match":{
"BMI_GIANT":"BMI","HEIGHT_GIANT":"HEIGHT","WHRadjBMI_GIANT":"WHRadjBMI","WHRU_GIANT":"WHR"
},
  "region parameter":"region",
  "overlapping regions":"true",
  "global enrichment plot labels":{"x axis":"","y axis":""},
  "star key":{"key":"Variant ID","position":"Position"}
},
"genes track": {"input type": "dynamic","dynamic parameter": "region"},
"zoom":"true"
}
